// Original art (ART spec Wave 0/1). Sprites are generated by
// assets/source/blender (make art) with sidecar metadata; this file is
// the presentation-only loader. Pixels and tints never reach the domain.

// artMetadataRel is the metadata tree relative to the assets root.
const artMetadataRel = "metadata"

// artScale is the export scale of generated sprites (@2x): one logical
// tile is artTilePx source pixels.
const (
	artScale  = 2
	artTilePx = TileSize * artScale
)

// artMeta is the subset of sprite metadata v1 the renderer consumes.
type artMeta struct {
	ID        string
	Image     string
	Canvas    [2]int
	Footprint [2]int
	Origin    [2]float64
	TintGroup string
	TintMask  string
	Attach    map[string][2]float64
	// Shadow is how the sprite casts a moving shadow (ART §6.1): kind
	// "blob", "box" or "none" (or empty: none), and its footprint width W,
	// height above ground H and depth D, in tiles.
	Shadow artShadow
}

// artShadow is a sprite's shadow caster (metadata "shadow:").
type artShadow struct {
	Kind    string
	W, H, D float64
}

// parseArtMeta reads the flat YAML subset written by artlib/meta.py:
// top-level scalars, inline [a, b] pairs, and one level of nesting.
func parseArtMeta(src string) (artMeta, error) {
	m := artMeta{Attach: map[string][2]float64{}}
	parent := ""
	sc := bufio.NewScanner(strings.NewReader(src))
	for sc.Scan() {
		line := sc.Text()
		trim := strings.TrimSpace(line)
		if trim == "" || strings.HasPrefix(trim, "#") {
			continue
		}
		key, val, ok := strings.Cut(trim, ":")
		if !ok {
			return m, fmt.Errorf("bad metadata line %q", line)
		}
		val = strings.Trim(strings.TrimSpace(val), `"`)
		nested := strings.HasPrefix(line, " ")
		if !nested {
			parent = ""
			if val == "" {
				parent = key
				continue
			}
		}
		var err error
		switch {
		case !nested && key == "id":
			m.ID = val
		case !nested && key == "image":
			m.Image = val
		case !nested && key == "canvas":
			m.Canvas, err = parseIntPair(val)
		case !nested && key == "footprint":
			m.Footprint, err = parseIntPair(val)
		case !nested && key == "origin_px":
			m.Origin, err = parsePair(val)
		case nested && parent == "tint" && key == "group":
			m.TintGroup = val
		case nested && parent == "tint" && key == "mask":
			m.TintMask = val
		case nested && parent == "shadow" && key == "kind":
			m.Shadow.Kind = val
		case nested && parent == "shadow" && (key == "w" || key == "h" || key == "d"):
			var f float64
			if f, err = strconv.ParseFloat(val, 64); err == nil {
				switch key {
				case "w":
					m.Shadow.W = f
				case "h":
					m.Shadow.H = f
				default:
					m.Shadow.D = f
				}
			}
		case nested && parent == "attachments":
			var p [2]float64
			p, err = parsePair(val)
			m.Attach[key] = p
		}
		if err != nil {
			return m, fmt.Errorf("%s: %w", key, err)
		}
	}
	if m.ID == "" || m.Image == "" || m.Canvas[0] < 1 || m.Canvas[1] < 1 {
		return m, fmt.Errorf("metadata missing id/image/canvas")
	}
	return m, sc.Err()
}

func parsePair(v string) ([2]float64, error) {
	var out [2]float64
	v = strings.TrimSpace(v)
	if !strings.HasPrefix(v, "[") || !strings.HasSuffix(v, "]") {
		return out, fmt.Errorf("want [a, b], got %q", v)
	}
	parts := strings.Split(v[1:len(v)-1], ",")
	if len(parts) != 2 {
		return out, fmt.Errorf("want 2 values, got %q", v)
	}
	for i, p := range parts {
		f, err := strconv.ParseFloat(strings.TrimSpace(p), 64)
		if err != nil {
			return out, err
		}
		out[i] = f
	}
	return out, nil
}

func parseIntPair(v string) ([2]int, error) {
	f, err := parsePair(v)
	return [2]int{int(f[0]), int(f[1])}, err
}

// parseTints reads `tints:` presets from palettes/base.yaml:
// group -> preset name -> colour.
func parseTints(src string) (map[string]map[string]color.NRGBA, error) {
	out := map[string]map[string]color.NRGBA{}
	in := false
	sc := bufio.NewScanner(strings.NewReader(src))
	for sc.Scan() {
		line := sc.Text()
		if !strings.HasPrefix(line, " ") {
			in = strings.HasPrefix(line, "tints:")
			continue
		}
		if !in {
			continue
		}
		group, body, ok := strings.Cut(strings.TrimSpace(line), ":")
		body = strings.TrimSpace(body)
		if !ok || !strings.HasPrefix(body, "{") || !strings.HasSuffix(body, "}") {
			continue
		}
		g := map[string]color.NRGBA{}
		for _, kv := range strings.Split(body[1:len(body)-1], ",") {
			k, v, ok := strings.Cut(kv, ":")
			if !ok {
				continue
			}
			c, err := parseHex(strings.Trim(strings.TrimSpace(v), `"`))
			if err != nil {
				return nil, fmt.Errorf("tint %s.%s: %w", group, strings.TrimSpace(k), err)
			}
			g[strings.TrimSpace(k)] = c
		}
		out[group] = g
	}
	return out, sc.Err()
}

func parseHex(h string) (color.NRGBA, error) {
	h = strings.TrimPrefix(h, "#")
	if len(h) != 6 {
		return color.NRGBA{}, fmt.Errorf("bad hex %q", h)
	}
	v, err := strconv.ParseUint(h, 16, 32)
	if err != nil {
		return color.NRGBA{}, err
	}
	return color.NRGBA{R: uint8(v >> 16), G: uint8(v >> 8), B: uint8(v), A: 255}, nil
}

// tintNRGBA multiplies src by tint where mask is white (mask red channel
// is coverage). Pure; used once per (sprite, tint) and cached.
func tintNRGBA(src, mask *image.NRGBA, tint color.NRGBA) *image.NRGBA {
	b := src.Bounds()
	dst := image.NewNRGBA(b)
	copy(dst.Pix, src.Pix)
	if mask == nil {
		return dst
	}
	tc := [3]uint32{uint32(tint.R), uint32(tint.G), uint32(tint.B)}
	for y := b.Min.Y; y < b.Max.Y; y++ {
		for x := b.Min.X; x < b.Max.X; x++ {
			i := dst.PixOffset(x, y)
			if !(image.Point{X: x, Y: y}).In(mask.Bounds()) {
				continue
			}
			k := uint32(mask.Pix[mask.PixOffset(x, y)])
			if k == 0 {
				continue
			}
			for c := 0; c < 3; c++ {
				v := uint32(dst.Pix[i+c])
				mul := v * tc[c] / 255
				dst.Pix[i+c] = uint8((v*(255-k) + mul*k) / 255)
			}
		}
	}
	return dst
}

type artSprite struct {
	meta artMeta
	pix  *image.NRGBA
	mask *image.NRGBA
	img  *ebiten.Image
	// normalPath is the sprite's normal map (<image>_n.png, ART §6.1), ""
	// when it has none; normal is its GPU image, loaded on first draw.
	normalPath string
	normal     *ebiten.Image
	normalDone bool
	// src is where an atlas-packed sprite's pixels come from (art_atlas.go);
	// nil for a sprite loaded from its own files. pix and mask are cut out
	// of the atlas the first time the catalog hands the sprite out.
	src *atlasSrc
	// opaqueH caches opaqueHeightPx (0: not measured yet).
	opaqueH float64
}

// opaqueAlphaMin is the alpha (0..255) a pixel needs to count as part of
// a sprite's body when measuring it (faint glow and anti-aliasing don't).
const opaqueAlphaMin = 32

// opaqueHeightPx is the height of the sprite's opaque part, from its
// alpha bounds, in canvas (source) pixels: measured once and cached. A
// sprite without opaque pixels reports its canvas height. It calibrates
// a creature's shadow (ART-012: κ = shadow.h / opaque height).
func (sp *artSprite) opaqueHeightPx() float64 {
	if sp.opaqueH > 0 {
		return sp.opaqueH
	}
	h := float64(sp.meta.Canvas[1])
	if sp.pix != nil {
		b := sp.pix.Bounds()
		top, bot := -1, -1
		for y := b.Min.Y; y < b.Max.Y; y++ {
			row := sp.pix.Pix[sp.pix.PixOffset(b.Min.X, y):]
			for x := 0; x < b.Dx(); x++ {
				if row[4*x+3] >= opaqueAlphaMin {
					if top < 0 {
						top = y
					}
					bot = y
					break
				}
			}
		}
		if top >= 0 && b.Dy() > 0 {
			k := 1.0
			if sp.meta.Canvas[1] > 0 {
				k = float64(sp.meta.Canvas[1]) / float64(b.Dy())
			}
			h = float64(bot-top+1) * k
		}
	}
	sp.opaqueH = math.Max(h, 1)
	return sp.opaqueH
}

type tintKey struct {
	key  string
	tint color.NRGBA
}

// artCatalog is the loaded original sprite set. Decoded pixels live on
// the CPU; GPU images are created lazily on first draw.
type artCatalog struct {
	sprites map[string]*artSprite // "family/name"
	tints   map[string]map[string]color.NRGBA
	tinted  map[tintKey]*ebiten.Image
	// normals maps every drawn sprite image (tinted or not) to its normal
	// map, for the lit draw (light.go).
	normals map[*ebiten.Image]*ebiten.Image
}

// LocateArt finds assets/metadata above the working directory or the
// executable (assetroot) and returns the assets root.
func LocateArt() (string, error) {
	root, err := assetroot.FindParent("assets", artMetadataRel, true)
	if err != nil {
		return "", fmt.Errorf("original art: %w; run make art", err)
	}
	return root, nil
}

// loadArtCatalog reads every world sprite's metadata, PNG and tint mask
// under root (the assets directory).
func loadArtCatalog(root string) (*artCatalog, error) {
	c := &artCatalog{sprites: map[string]*artSprite{}, tinted: map[tintKey]*ebiten.Image{},
		normals: map[*ebiten.Image]*ebiten.Image{}}
	base, err := os.ReadFile(filepath.Join(root, "palettes", "base.yaml"))
	if err != nil {
		return nil, err
	}
	if c.tints, err = parseTints(string(base)); err != nil {
		return nil, err
	}
	metaRoot := filepath.Join(root, artMetadataRel)
	families, err := os.ReadDir(metaRoot)
	if err != nil {
		return nil, err
	}
	for _, fam := range families {
		if !fam.IsDir() || fam.Name() == menuMetaFamily || fam.Name() == atlasMetaDir { // not sprite families
			continue
		}
		if _, err := os.Stat(filepath.Join(metaRoot, atlasMetaDir, fam.Name()+".yaml")); err == nil {
			continue // packed by cmd/atlasgen: served from its atlas pages below
		}
		files, err := os.ReadDir(filepath.Join(metaRoot, fam.Name()))
		if err != nil {
			return nil, err
		}
		for _, f := range files {
			if !strings.HasSuffix(f.Name(), ".yaml") {
				continue
			}
			raw, err := os.ReadFile(filepath.Join(metaRoot, fam.Name(), f.Name()))
			if err != nil {
				return nil, err
			}
			m, err := parseArtMeta(string(raw))
			if err != nil {
				return nil, fmt.Errorf("%s/%s: %w", fam.Name(), f.Name(), err)
			}
			sp := &artSprite{meta: m}
			if sp.pix, err = decodeNRGBA(filepath.Join(root, filepath.FromSlash(m.Image))); err != nil {
				return nil, err
			}
			if m.TintMask != "" {
				if sp.mask, err = decodeNRGBA(filepath.Join(root, filepath.FromSlash(m.TintMask))); err != nil {
					return nil, err
				}
			}
			np := filepath.Join(root, filepath.FromSlash(strings.TrimSuffix(m.Image, ".png")+"_n.png"))
			if _, err := os.Stat(np); err == nil {
				sp.normalPath = np
			}
			c.sprites[fam.Name()+"/"+strings.TrimSuffix(f.Name(), ".yaml")] = sp
		}
	}
	// Packed families (metadata/atlas/<family>.yaml), whether or not their
	// individual files are still around.
	packed, _ := filepath.Glob(filepath.Join(metaRoot, atlasMetaDir, "*.yaml"))
	for _, p := range packed {
		if err := c.loadAtlas(root, strings.TrimSuffix(filepath.Base(p), ".yaml")); err != nil {
			return nil, err
		}
	}
	if len(c.sprites) == 0 {
		return nil, fmt.Errorf("no sprites under %s", metaRoot)
	}
	return c, nil
}

func decodeNRGBA(path string) (*image.NRGBA, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	src, err := png.Decode(f)
	if err != nil {
		return nil, fmt.Errorf("%s: %w", path, err)
	}
	if n, ok := src.(*image.NRGBA); ok {
		return n, nil
	}
	dst := image.NewNRGBA(src.Bounds())
	draw.Draw(dst, dst.Bounds(), src, src.Bounds().Min, draw.Src)
	return dst, nil
}

func (c *artCatalog) has(key string) bool {
	if c == nil {
		return false
	}
	_, ok := c.sprites[key]
	return ok
}

func (c *artCatalog) sprite(key string) *artSprite {
	if c == nil {
		return nil
	}
	sp := c.sprites[key]
	if sp != nil && sp.src != nil && sp.pix == nil {
		sp.src.fill(sp)
	}
	return sp
}

// image returns the GPU texture for key, tinted when the sprite has a
// mask and tint is non-zero.
func (c *artCatalog) image(key string, tint color.NRGBA) *ebiten.Image {
	sp := c.sprite(key)
	if sp == nil {
		return nil
	}
	if sp.mask == nil || tint.A == 0 {
		if sp.img == nil {
			sp.img = ebiten.NewImageFromImage(sp.pix)
			c.linkNormal(sp.img, sp)
		}
		return sp.img
	}
	k := tintKey{key: key, tint: tint}
	if img, ok := c.tinted[k]; ok {
		return img
	}
	img := ebiten.NewImageFromImage(tintNRGBA(sp.pix, sp.mask, tint))
	c.tinted[k] = img
	c.linkNormal(img, sp)
	return img
}

// linkNormal records sp's normal map (decoded once) as img's.
func (c *artCatalog) linkNormal(img *ebiten.Image, sp *artSprite) {
	if !sp.normalDone {
		sp.normalDone = true
		var n *image.NRGBA
		if sp.src != nil {
			n = sp.src.normalImage(sp)
		} else if sp.normalPath != "" {
			n, _ = decodeNRGBA(sp.normalPath)
		}
		if n != nil && n.Bounds().Size() == sp.pix.Bounds().Size() {
			sp.normal = ebiten.NewImageFromImage(n)
		}
	}
	if sp.normal != nil && c.normals != nil {
		c.normals[img] = sp.normal
	}
}

// normalOf is img's normal map, nil when it has none (flat).
func (c *artCatalog) normalOf(img *ebiten.Image) *ebiten.Image {
	if c == nil {
		return nil
	}
	return c.normals[img]
}

// tint returns preset name from group (e.g. "hair", "black").
func (c *artCatalog) tint(group, name string) color.NRGBA {
	if c == nil {
		return color.NRGBA{}
	}
	return c.tints[group][name]
}

func (c *artCatalog) tintNames(group string) []string {
	if c == nil {
		return nil
	}
	names := make([]string, 0, len(c.tints[group]))
	for n := range c.tints[group] {
		names = append(names, n)
	}
	sort.Strings(names)
	return names
}

// --- pure presentation rules -------------------------------------------

// Wall autotile mask bits (ART spec / assets/AGENTS.md); linkgrid.go
// computes the masks.
const (
	wallN = 1
	wallE = 2
	wallS = 4
	wallW = 8
)

// facing is a presentation-only pawn orientation.
type facing uint8

const (
	faceSouth facing = iota
	faceEast
	faceNorth
	faceWest
)

func (f facing) String() string {
	return [...]string{"south", "east", "north", "west"}[f]
}

// facingFor picks orientation from a tile step; no step keeps prev.
func facingFor(dx, dy int, prev facing) facing {
	ax, ay := dx, dy
	if ax < 0 {
		ax = -ax
	}
	if ay < 0 {
		ay = -ay
	}
	switch {
	case ax == 0 && ay == 0:
		return prev
	case ax >= ay && dx > 0:
		return faceEast
	case ax >= ay:
		return faceWest
	case dy > 0:
		return faceSouth
	default:
		return faceNorth
	}
}

// pawnLook is a colonist's presentation appearance, derived from its
// EntityID (stable, not RNG; never written back to the simulation).
type pawnLook struct {
	Skin, Hair, HairStyle, Shirt, Pants, Vest string // tint preset names / layer name
}

var hairStyles = []string{"hair_short", "hair_crop", "hair_bun"}

func mix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xBF58476D1CE4E5B9
	x ^= x >> 27
	x *= 0x94D049BB133111EB
	x ^= x >> 31
	return x
}

func lookFor(id uint64, skins, hairs, cloths []string) pawnLook {
	pick := func(salt uint64, opts []string) string {
		if len(opts) == 0 {
			return ""
		}
		return opts[mix64(id*0x9E3779B97F4A7C15+salt)%uint64(len(opts))]
	}
	l := pawnLook{
		Skin:      pick(1, skins),
		Hair:      pick(2, hairs),
		HairStyle: pick(3, hairStyles),
		Shirt:     pick(4, cloths),
		Pants:     pick(5, cloths),
	}
	if mix64(id+6)%2 == 0 {
		l.Vest = pick(7, cloths)
	}
	if l.Pants == l.Shirt && len(cloths) > 1 {
		for _, c := range cloths {
			if c != l.Shirt {
				l.Pants = c
				break
			}
		}
	}
	return l
}

// artOrigin converts a sprite's footprint anchor to a screen position:
// the footprint's top-left lands at (sx, sy); scale is tile/artTilePx.
func artOrigin(m artMeta, sx, sy, tile float64) (x, y, scale float64) {
	scale = tile / artTilePx
	return sx - m.Origin[0]*scale, sy - m.Origin[1]*scale, scale
}
